local _, WFJ = ...
WFJ.Data.add("quest", {
  [94003] = { "Lo Skybreaker Bulwark", "Recupera il ⟦Skybreaker Bulwark=Baluardo Fendicielo⟧ da Zaal Stormshield al ⟦Shrine of Akir=Sacrario di Akir⟧.", "Sono tutto ciò che resta della stirpe degli Skybreaker qui sull'isola di Zephras. Gli altri sono stati assassinati dagli Al'Aketh.\n\nL'unica cosa che supera il mio dolore è la mia vergogna. Lo scudo ancestrale della mia famiglia, il ⟦Skybreaker Bulwark=Baluardo Fendicielo⟧, è ora nelle mani di un cultista di nome Zaal Stormshield. Secondo le leggende di famiglia, nessun male può colpire chi impugna questo scudo ed è degno di esso.\n\nZaal non ne è degno, di questo sono certo. Trova quell'uomo al ⟦Shrine of Akir=Sacrario di Akir⟧ e riprenditi il mio scudo. Fallo e ti insegnerò la Skybreaker Defense.", "<Seena ti rivolge un breve cenno del capo.>", "Hai fatto ciò che io non ho potuto e hai ripristinato l'onore della mia famiglia. Per questo, ti concederò un dono che pochi su Zephras sono degni di ricevere. Ti insegnerò i segreti della Difesa Fendicielo.\n\nInoltre, ti servirà uno scudo per mettere in pratica ciò che ho da insegnarti. Ti prego, prendi questo. Non mi serve più ora che il Baluardo Fendicielo mi è stato restituito.\n\nBanu'Adoraah, <amico/amica>.", 0xeef30912, 0x2a671f64, 0x9c8826cf, 0x962bb69e, 0x0b6cabf7, "....." },
  [94004] = { "Contratto d'Artigianato: Elisir della Forza degli Ogre", "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questo contratto.", "<Scritto con un inchiostro sbiadito, il biglietto richiede $N1 Elisir della Forza degli Ogre e riporta indicazioni sul luogo di consegna e sul pagamento. In fondo, una scritta indica che il contratto è cedibile.>", nil, nil, 0x96235fbe, 0x89b8e7e5, 0xceb296e5, nil, nil, "...mm" },
  [94006] = { "Il Grande Spirito Ursera", "Parla con Urs'endris vicino alle cascate a nord-est di Valanaar.", "Salute, {name}. Sei andat<o/a> abbastanza avanti nei tuoi studi druidici da farmi pensare che sia ora di conoscere uno dei grandi spiriti che dimorano qui a Zephras. Urs'endris è uno spirito saggio e nobile, che da generazioni insegna ai druidi ad assumere la forma di ursera. Purtroppo il suo dominio ha cominciato ad avvizzire e a precipitare nel cielo, come molte altre zone di Zephras.\n\nPer trovarlo, va' a nord-est, vicino alla cascata all'ombra del ⟦Shrine of Akir=Sacrario di Akir⟧. Lui saprà guidarti oltre.", nil, "Dunque desideri abbracciare la via dell'artiglio, giovane? Molto bene. Parliamo.", 0xd845fe86, 0x00a57812, 0x6204789e, nil, 0xbbf0f14d, "...m." },
  [94007] = { "Addomesticare la bestia", "Fai rapporto a Quel'ana Quickgale a Valanaar.", "Ora che hai preso una certa confidenza con le terre selvagge degli altopiani, credo sia giunto il momento che tu cerchi un compagno animale tutto tuo.\n\nVa' al porto di Valanaar, a sud-est, e parla con Quel'ana Quickgale. Ti istruirà nell'arte di ammansire le bestie.", nil, "Mi fa molto piacere che tu sia venut<o/a>. Vieni, cominciamo.", 0xecd97a9a, 0x87db1216, 0xab76e227, nil, 0xf4512a31, "...m." },
  [94013] = { "Addomesticare la bestia", "Usa il ⟦Taming Rod=Bastone per Addomesticare⟧ per ammansire un Vuldren Alpha nelle ⟦Gustberry Lowlands=Pianure di Ventobacca⟧. Esercita le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Quel'ana Quickgale a Valanaar.", "Sei <tornato/tornata> vittorios<o/a> dopo aver ammansito due bestie. Ora è il momento della tua ultima prova. I venti di Zephras sussurrano di sfide più grandi in arrivo.\n\nPrendi questo ⟦Taming Rod=Bastone per Addomesticare⟧ e recati nelle ⟦Gustberry Lowlands=Pianure di Ventobacca⟧. Lì ammansisci un Vuldren Alpha e dimostra la tua maestria.\n\nCompleta questa lezione e sarai <pronto/pronta> ad apprendere le vie più profonde del cacciatore.", "Imparerai, {name}, e un giorno sarai <un/una> grande {class}.", "Eccellente, {name}! Impari davvero in fretta. Ora che conosci le basi, posso insegnarti a stringere un legame duraturo con un compagno animale.\n\nVa' con questa conoscenza e prospera. Sii <il/la> {class} di cui l'isola di Zephras ha bisogno.", 0xecd97a9a, 0xd6749188, 0x420fabee, 0xe5057f89, 0x5c64ed8c, "....." },
  [94050] = { "Addestrare la bestia", "Parla con Quel'dora Quickgale a Valanaar.", "Ora hai il potere di addomesticare un famiglio, ma devi anche acquisire le capacità per addestrarlo. Per questo non c'è nessuno migliore di mia sorella, Quel'dora. Ti darà la capacità di addestrare il tuo nuovo famiglio.\n\nVa' con i venti, giovane {class}.", nil, "<Un/Una> {class} alle prime armi, vedo. Sì, posso darti le capacità che ti servono per addestrare e guidare il tuo famiglio. Non solo potrai insegnare al tuo famiglio nuove abilità, ma d'ora in poi potrai anche nutrirlo e riportarlo in vita, se dovesse cadere in battaglia.\n\nRicorda, {name}, rispetta sempre l'equilibrio e vivi con riverenza verso la natura che ti circonda. Ora va'. Ci parleremo di nuovo più avanti.", 0xdbeedc0e, 0xa8d2fa5d, 0x1f82d9d8, nil, 0xfbd746d0, "...m." },
